    var span = step * Math.max(0, tier1.length - 1);
    if (span > MAX_ARC) { step = MAX_ARC / Math.max(1, tier1.length - 1); span = MAX_ARC; }

    var base = 2.399963 - span / 2;   // golden-angle base so it is never dead flat
